This PR brings a new chapter that describes the following transformations:

- Replacing null values;
- Removing duplicated values;
- Merging multiple DataFrames with UNION operations;
- Merging multiple DataFrames with JOIN operations;
- Rows to columns with Pivot operations;
- Collecting and explode operations;

## 🔥 관련 이슈

close #75 

## 🔥 PR Point

- BottomBar visible 구현
- home -> histroy 네비게이션 연결
- history -> history_detail 네비게이션 연결

## 🔥 To Reviewers
아래와 같이 NavHost에서 graph들에게 navController을 전달하고 graph 내부에서 람다를 사용하도록 코드 구현했습니다!
NavHost 코드가 길어지지 않게 하기 위해 이렇게 구현했는데 Controller 전달만 하는것 같아서 NavHost에서 바로 람다를 만들지, 고민이되네용 의견주시면 감사하겠습니다!

```kotlin 
@Composable
fun TwoTooNavHost(
    appState: TwoTooAppState,
    modifier: Modifier = Modifier,
    startDestination: String = HomeNavigationRoute,
) {
    val navController = appState.navController
    NavHost(
        navController = navController,
        startDestination = startDestination,
        modifier = modifier,
    ) {
        gardenGraph()
        homeGraph(navController = navController)
        userGraph()
        onBoardingGraph()
        historyGraph(navController = navController)
        historyDetailGraph(navController = navController)
    }
}


fun NavGraphBuilder.historyGraph(navController: NavController) {
    composable(route = HistoryNavigationRoute) {
        HistoryRoute(
            onClickBackButton = { navController.popBackStack() },
            navigateToHistoryDetail = {
                navController.navigateToHistoryDetail(
                    navOptions {
                        popUpTo(HistoryNavigationRoute) {
                            saveState = true
                        }
                        launchSingleTop = true
                        restoreState = true
                    },
                )
            },
        )
    }
}

```

